#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long n = strtol(argv[1], &end1, 10);
    long m = strtol(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (m < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (m > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    double sum = 0.0;
    if (n == 1) {
        for (long i = 1; i <= m; ++i) {
            sum += 1.0 / ((double)i * (double)i);
        }
    } else if (n == 2) {
        for (long i = 1; i <= m; ++i) {
            sum += 1.0 / (double)i;
        }
    } else if (n == 3) {
        sum = 1.0; // initial term as observed in the original binary
        for (long i = 1; i <= m; ++i) {
            sum += 1.0 / (double)i;
        }
    } else {
        puts("BAD_MODE");
        return 0;
    }
    printf("%.6f\n", sum);
    return 0;
}
}
